const body = $json.body && typeof $json.body === 'object' ? $json.body : $json;
const allowed = new Set(['schema_version','event_id','event_type','account_case_id','message_id','reply_intent','case_type','case_title','zendesk_ticket_id','zendesk_url','ticket_summary','message_text']);
const keys = Object.keys(body);
if (keys.some(key => !allowed.has(key))) throw new Error('unsupported_event_field');
if (Number(body.schema_version) !== 1 || String(body.event_type || '') !== 'account_automation_handoff_confirmed') throw new Error('invalid_event_contract');
const event = {};
for (const key of allowed) event[key] = body[key];
for (const key of ['event_id','account_case_id','message_id','reply_intent','case_type','case_title','zendesk_ticket_id','zendesk_url','ticket_summary','message_text']) {
  if (!String(event[key] ?? '').trim()) throw new Error(`missing_event_field:${key}`);
}
if (!/^account-automation-slack:[^:]+:[^:]+$/.test(String(event.event_id))) throw new Error('invalid_event_id');
return [{ json: { event, event_id: String(event.event_id) } }];
